#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
in highp vec4 in_POSITION0;
in highp vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out highp vec2 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    vs_COLOR0 = in_COLOR0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _DispTiling;
uniform 	vec4 _DispScroll;
uniform 	float _DispStrength;
uniform 	float _WaveAmp;
uniform 	float _WaveFreq;
uniform 	float _WaveSpeed;
uniform 	float _Phase;
uniform 	float _T;
UNITY_LOCATION(0) uniform mediump sampler2D _DispTex;
UNITY_LOCATION(1) uniform mediump sampler2D _MainTex;
in mediump  vec4 vs_COLOR0;
in highp  vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
float u_xlat0;
bool u_xlatb0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec2 u_xlat2;
vec3 u_xlat3;
mediump float u_xlat16_3;
float u_xlat6;
vec2 u_xlat7;
void main()
{
    u_xlat0 = vs_TEXCOORD0.x * _WaveFreq;
    u_xlat3.x = _Phase + _T;
    u_xlat6 = u_xlat3.x * _WaveSpeed;
    u_xlat3.xz = u_xlat3.xx * _DispScroll.xy;
    u_xlat3.xz = vs_TEXCOORD0.xy * _DispTiling.xy + u_xlat3.xz;
    u_xlat1.xy = vec2(u_xlat6) * vec2(0.349999994, 0.550000012);
    u_xlat0 = u_xlat0 * 2.29999995 + (-u_xlat1.y);
    u_xlat6 = vs_TEXCOORD0.x * _WaveFreq + u_xlat1.x;
    u_xlat6 = u_xlat6 * 6.28319979;
    u_xlat6 = sin(u_xlat6);
    u_xlat6 = u_xlat6 * 0.5 + 0.5;
    u_xlat0 = u_xlat0 * 6.28319979 + 1.70000005;
    u_xlat0 = sin(u_xlat0);
    u_xlat0 = u_xlat0 * 0.5 + 0.5;
    u_xlat0 = u_xlat0 * 0.400000006;
    u_xlat0 = u_xlat6 * 0.600000024 + u_xlat0;
    u_xlat0 = (-_WaveAmp) * u_xlat0 + 1.0;
    u_xlat1.y = vs_TEXCOORD0.y / u_xlat0;
    u_xlatb0 = u_xlat0>=vs_TEXCOORD0.y;
    u_xlat0 = u_xlatb0 ? 1.0 : float(0.0);
    u_xlat7.xy = u_xlat3.xz + vec2(0.370000005, 0.610000014);
    u_xlat16_3 = texture(_DispTex, u_xlat3.xz).x;
    u_xlat2.x = u_xlat16_3 + -0.5;
    u_xlat16_3 = texture(_DispTex, u_xlat7.xy).x;
    u_xlat2.y = u_xlat16_3 + -0.5;
    u_xlat1.x = vs_TEXCOORD0.x;
    u_xlat3.xy = u_xlat2.xy * vec2(_DispStrength) + u_xlat1.xy;
    u_xlat3.xy = max(u_xlat3.xy, vec2(0.00200000009, 0.00200000009));
    u_xlat3.xy = min(u_xlat3.xy, vec2(0.998000026, 0.998000026));
    u_xlat16_1 = texture(_MainTex, u_xlat3.xy);
    u_xlat1 = u_xlat16_1 * vs_COLOR0;
    u_xlat1.w = u_xlat0 * u_xlat1.w;
    SV_Target0 = u_xlat1;
    return;
}
